const CACHE_NAME = 'biptach-v1';
const OFFLINE_URL = '/index.html';

// Install: cache the app shell and all static assets
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(async (cache) => {
      // Cache the offline fallback page
      await cache.add(OFFLINE_URL);
      
      // Get all URLs from the precache manifest (generated by Vite)
      // For now, cache the main entry points
      const urlsToCache = [
        '/',
        '/index.html',
        '/manifest.json',
        '/favicon.svg'
      ];
      
      await cache.addAll(urlsToCache);
      
      // Cache all JS and CSS files from the current page
      const cacheList = await caches.open(CACHE_NAME);
      const keys = await cacheList.keys();
      console.log('Service worker installed, cached', keys.length, 'requests');
    })
  );
  self.skipWaiting();
});

// Activate: clean up old caches
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheName !== CACHE_NAME) {
            console.log('Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  self.clients.claim();
});

// Fetch: network-first with cache fallback, then cache all successful responses
self.addEventListener('fetch', event => {
  // Skip non-GET requests
  if (event.request.method !== 'GET') return;
  
  // Skip Supabase API calls (they need to be online)
  if (event.request.url.includes('supabase.co')) return;
  
  event.respondWith(
    fetch(event.request)
      .then(response => {
        // Clone the response before caching
        const responseClone = response.clone();
        
        // Cache successful responses
        if (response.status === 200) {
          caches.open(CACHE_NAME).then(cache => {
            cache.put(event.request, responseClone);
          });
        }
        
        return response;
      })
      .catch(() => {
        // Network failed, try cache
        return caches.match(event.request).then(response => {
          if (response) {
            return response;
          }
          
          // For navigation requests, return the offline page
          if (event.request.mode === 'navigate') {
            return caches.match(OFFLINE_URL);
          }
          
          // For other requests, return a generic offline response
          return new Response('Offline', {
            status: 503,
            statusText: 'Service Unavailable',
            headers: { 'Content-Type': 'text/plain' }
          });
        });
      })
  );
});
